def P(t, style='Small'): return Paragraph(t, styles[style])
def table(rows,widths=None):
    t=Table([[P(c) for c in r] for r in rows],colWidths=widths,repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.white),('TEXTCOLOR',(0,0),(-1,0),colors.black),('FONTNAME',(0,0),(-1,0),'Times-Bold'),('GRID',(0,0),(-1,-1),.5,colors.black),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]));return t
def footer(canvas,doc):
    canvas.saveState();canvas.setFont('Times-Roman',8);canvas.setFillColor(colors.black);canvas.drawString(1.6*cm,.75*cm,'EpiScope - synthetic teaching prototype');canvas.drawRightString(19.4*cm,.75*cm,f'Page {doc.page}');canvas.restoreState()
story=[]
